#!/usr/bin/env python3
"""Turn the price list people edit into the one the broker charges from.

see docs/inline/site/bin/build-prices.py.md#1"""

import argparse
import json
import pathlib
import sys

import yaml

# see docs/inline/site/bin/build-prices.py.md#2
SITE = pathlib.Path(__file__).resolve().parent.parent
REPO = SITE.parent
OUT = REPO / "worker" / "src" / "prices.js"

BANNER = """\
// GENERATED by site/bin/build-prices.py; do not edit. See docs/inline/worker/src/prices.js.md#1

export default """

# see docs/inline/site/bin/build-prices.py.md#3
CENTS = 100


def load(name):
    with open(SITE / "_data" / name, encoding="utf-8") as handle:
        return yaml.safe_load(handle)


def amount(value):
    """see docs/inline/site/bin/build-prices.py.md#4"""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    if value <= 0:
        return None
    cents = round(value * CENTS)
    # see docs/inline/site/bin/build-prices.py.md#5
    if abs(value * CENTS - cents) > 0.001:
        return None
    return int(cents)


def slug(name):
    return "".join(character.lower() if character.isalnum() else "-" for character in name).strip("-")


def build():
    """The catalog, plus the reasons anything was left out of it."""
    items = {}
    skipped = []

    membership = load("membership.yml")

    for tier in membership.get("tiers") or []:
        cents = amount(tier.get("price"))
        sku = f"membership:{slug(tier['name'])}"
        if cents is None:
            skipped.append(f"{sku} — price is {tier.get('price')!r}")
            continue
        items[sku] = {
            "kind": "membership",
            "name": f"{tier['name']} membership",
            # see docs/inline/site/bin/build-prices.py.md#6
            "description": "One year from today. Renews on the day you joined, not in January.",
            "amount": cents,
            # see docs/inline/site/bin/build-prices.py.md#7
            "interval": "year",
        }

    # see docs/inline/site/bin/build-prices.py.md#8
    classes = load("classes.yml")
    dropin = classes.get("dropin") or {}
    for who in ("public", "member"):
        cents = amount(dropin.get(who))
        sku = f"class-dropin:{who}"
        if cents is None:
            skipped.append(f"{sku} — price is {dropin.get(who)!r}")
            continue
        items[sku] = {
            "kind": "class",
            "name": f"Class drop-in ({who})",
            "description": "Attendance at one class session.",
            "amount": cents,
            "interval": None,
        }

    return {"currency": "usd", "items": items}, skipped


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--check",
        action="store_true",
        help="fail if the committed file has drifted from the data files",
    )
    args = parser.parse_args()

    catalog, skipped = build()
    rendered = BANNER + json.dumps(catalog, indent=2, sort_keys=True) + ";\n"

    if args.check:
        current = OUT.read_text(encoding="utf-8") if OUT.exists() else ""
        if current != rendered:
            print(
                f"{OUT.relative_to(REPO)} is out of date.\n"
                "A price changed in site/_data/ without the broker's copy being "
                "rebuilt. Run:\n\n    python3 site/bin/build-prices.py\n\n"
                "and commit the result.",
                file=sys.stderr,
            )
            return 1
        print(f"{OUT.relative_to(REPO)} matches the data files.")
    else:
        OUT.parent.mkdir(parents=True, exist_ok=True)
        OUT.write_text(rendered, encoding="utf-8")
        print(f"Wrote {OUT.relative_to(REPO)} — {len(catalog['items'])} for sale.")

    for note in skipped:
        print(f"  not for sale: {note}")

    return 0


if __name__ == "__main__":
    sys.exit(main())
